double sum = 0.0;
const unsigned int lcg_a = 1664525u;
const unsigned int lcg_c = 1013904223u;
const unsigned int lcg_m = 1u << 31;  // 2^31

unsigned int cur = seed;
for (int i = 0; i < n_points; ++i) {
    cur = (static_cast<unsigned long long>(lcg_a) * cur + lcg_c) % lcg_m;
    double u = static_cast<double>(cur) / static_cast<double>(lcg_m);  // uniform [0,1)
    double x = a + (b - a) * u;
    sum += f(x);
}
seed = cur;  // update external seed
double mean = sum / static_cast<double>(n_points);
return mean * (b - a);

